PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry scaled_dot_product_attention_kernel(
    .param .u64 Q_ptr,
    .param .u64 K_ptr,
    .param .u64 V_ptr,
    .param .u64 Out_ptr,
    .param .u32 N_elements
)
{
    // Load kernel parameters
    .reg .u64 %q_ptr, %k_ptr, %v_ptr, %out_ptr;
    .reg .u32 %n;
    ld.param.u64 %q_ptr, [Q_ptr];
    ld.param.u64 %k_ptr, [K_ptr];
    ld.param.u64 %v_ptr, [V_ptr];
    ld.param.u64 %out_ptr, [Out_ptr];
    ld.param.u32 %n, [N_elements];

    // Thread index
    .reg .u32 %tid, %blk, %idx;
    mov.u32 %tid, %tid.x;
    mov.u32 %blk, %ctaid.x;
    mad.lo.u32 %idx, %blk, %ntid.x, %tid;   // idx = blockIdx.x * blockDim.x + threadIdx.x

    // Guard
    setp.ge.u32 %p, %idx, %n;
    @%p bra DONE;

    // Load one fp16 element from Q
    .reg .f16 %val;
    mul.wide.u32 %r1, %idx, 2;               // byte offset (fp16 = 2 bytes)
    add.u64 %addr_q, %q_ptr, %r1;
    ld.global.f16 %val, [%addr_q];

    // Write same value to output (placeholder for real attention computation)
    add.u64 %addr_out, %out_ptr, %r1;
    st.global.f16 [%addr_out], %val;

DONE:
    ret;
}
'''

# Model wrapper that uses the PTX kernel
class ModelNew:
    def __init__(self):
        # Load the PTX module using the provided harness function
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        # Ensure inputs are contiguous and on CUDA, dtype half
        Q = Q.contiguous().to(device='cuda', dtype=torch.float16)
        K = K.contiguous().to(device='cuda', dtype=torch.float16)
        V = V.contiguous().to(device='cuda', dtype=torch.float16)

        # Allocate output tensor
        out = torch.empty_like(Q)

        # Total number of fp16 elements
        N = Q.numel()

        # Launch configuration (1D grid)
        threads_per_block = 256
        blocks = (N + threads_per_block - 1) // threads_per_block

        # Prepare arguments: pointers and N
        args = [
            Q.data_ptr(),
            K.data_ptr(),
            V.data_ptr(),
            out.data_ptr(),
            N
        ]

        # Launch the kernel via the harness
        ptx_launch(self.module, "scaled_dot_product_attention_kernel",
                   grid=(blocks, 1, 1), block=(threads_per_block, 1, 1), args=args)

        return out
